import React, { createContext, useRef, useEffect, useState } from "react";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { Translation, useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import { Card } from "react-bootstrap";
import { Button } from "@mui/material";
import Level1 from "../Img/Level1.png";
import Level2 from "../Img/Level2.png";

function LevelstartMidContent({}) {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const txt = useRef(0);
  var flag = "0"; //landscape

  const [pageName, setPageName] = useState("levelchoice_page");

  useEffect(() => {
    //Runs on every render
  });

  const handlelevel1 = () => {
    //GA
    ReactGA.event({
      action: "L04 | level_start",
      category: "L04 | Level_one(star1)_button_clicked",
      label: "Level_one(star1)_button_clicked",
    });
    navigate("/ll5_level1");
  };
  const handlelevel2 = () => {

     //GA
     ReactGA.event({
      action: "L04 | level_start",
      category: "L04 | Level_two(star2)_button_clicked",
      label: "Level_two(star2)_button_clicked",
    });
    navigate("/ll5_level2");
  };
  const handlelevel3 = () => {
    navigate("/start");
  };
  return (

    <div className="row scrollbar-primary">
        <div className="col animate__animated animate__bounceInUp d-flex justify-content-center align-items-center mb-3">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level1} />
            <Card.Body className="text-center">
              <Card.Title>विशेषण</Card.Title>
              <Button variant="contained" onClick={handlelevel1}>
                शुरू करें।
              </Button>
            </Card.Body>
          </Card>
        </div>
        <div className="col animate__animated animate__bounceInRight d-flex justify-content-center align-items-center mb-3">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level2} />
            <Card.Body className="text-center">
              <Card.Title>विशेष्य</Card.Title>
              <Button variant="contained" onClick={handlelevel2}>
                शुरू करें।
              </Button>
            </Card.Body>
          </Card>
        </div>
      </div>
    
  );
}

export default LevelstartMidContent;


