import { Footercomp, Theory } from "Hindi-olabsnxtg-library";
import { Headcomp } from "Hindi-olabsnxtg-library";
import { Middlecomp } from "Hindi-olabsnxtg-library";
import React from "react";
import hindi_bg from "../Img/hindi_bg.jpg";
import * as Instru from "../components/Instruction";
import { useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import { useTranslation } from "react-i18next";
import Level1First from "./Level1First";
import QuizPopupContent from "../quiz/QuizPopupContent";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";

const LL5_level_1 = () => {
  const { t, i18n } = useTranslation();
  const [instruct, setInstruct] = useState(Instru.Instruction_2(t));
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  ReactGA.send({
    hitType: "pageview",
    page: "#/ll5_level1",
    title: "L04 | Level_one_sangyakeprakar",
  });

  return (
    <div
      style={{
        height: "100vh",
        backgroundImage: "url(" + hindi_bg + ")",
        backgroundSize: "100% 100%",
        backgroundRepeat: "no-repeat",
        maxHeight: "100%",
      }}
    >
      <Theory
        H_title={t("title")}
        H_sidebarvisible="false"
        HQ_quittext={t("quitpopup")}
        HQ_yes={t("yes")}
        HQ_cancel={t("cancel")}
        RSM_QuizPopupContent_comp={<QuizPopupContent />} // here you have to add instructio of quiz (you can make a component and add it here)
        RSM_Intruc_popup_title_string={t("quizpophead")}
        RSM_ok={t("yes")}
        RSM_menu_tt={t("menu")}
        RSM_theory_tt={t("theory")}
        RSM_vivavoce_tt={t("vivavoce")}
        RSM_procedure_tt={t("quiz")}
        RSM_help_tt={t("help")}
        TT_midheight="90%"
        TT_midcontent_comp={<Level1First />} // here you have to add Theory (you can make a component and add it here)
        WS_sendJsonMessage={sendJsonMessage}
        WS_sendLogData={SendLogData}
        L_labName={t("title")}
        L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-04"
      />

      {/* <Footercomp
        F_footheight="15%"
        F_instruction={instruct}
        F_instructionlabel={t("instuhead")}
      /> */}
    </div>
  );
};

export default LL5_level_1;
